import sys


def is_valid(sequence: str) -> bool:
    matching = {")": "(", "]": "[", "}": "{"}
    stack = []

    for bracket in sequence:
        if bracket in "([{":
            stack.append(bracket)
        elif not stack or stack.pop() != matching[bracket]:
            return False

    return not stack


def main() -> None:
    first_line = sys.stdin.buffer.readline()
    if not first_line:
        return

    count = int(first_line)
    results = []
    for _ in range(count):
        sequence = sys.stdin.buffer.readline().decode().rstrip("\r\n")
        results.append("valid" if is_valid(sequence) else "invalid")

    if results:
        sys.stdout.write("\n".join(results) + "\n")


if __name__ == "__main__":
    main()

