    pairs = {ord(")"): ord("("), ord("]"): ord("["), ord("}"): ord("{")}
    stack: list[int] = []

    for bracket in line:
        if bracket in (ord("("), ord("["), ord("{")):
            stack.append(bracket)
        elif not stack or stack.pop() != pairs[bracket]:
            return False

    return not stack


def main() -> None:
    input_stream = sys.stdin.buffer
    count = int(input_stream.readline())
    results: list[str] = []

    for _ in range(count):
        line = input_stream.readline()
        if line.endswith(b"\n"):
            line = line[:-1]
        if line.endswith(b"\r"):
            line = line[:-1]
        results.append("valid" if is_valid(line) else "invalid")

    sys.stdout.write("\n".join(results))
    if results:
        sys.stdout.write("\n")


if __name__ == "__main__":
    main()

