use std::io::{self, Read};

fn is_valid(line: &str) -> bool {
    let mut stack = Vec::with_capacity(line.len());

    for bracket in line.bytes() {
        match bracket {
            b'(' | b'[' | b'{' => stack.push(bracket),
            b')' if stack.pop() != Some(b'(') => return false,
            b']' if stack.pop() != Some(b'[') => return false,
            b'}' if stack.pop() != Some(b'{') => return false,
            b')' | b']' | b'}' => {}
            _ => unreachable!("input contains only brackets"),
        }
    }

    stack.is_empty()
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    // split, unlike str::lines, retains a final empty line after a trailing newline.
    let mut lines = input.split('\n');
    let count: usize = lines
        .next()
        .unwrap_or("0")
        .trim_end_matches('\r')
        .parse()
        .unwrap();

    let mut output = String::new();
    for index in 0..count {
        let line = lines.next().unwrap_or("").trim_end_matches('\r');
        if index > 0 {
            output.push('\n');
        }
        output.push_str(if is_valid(line) { "valid" } else { "invalid" });
    }

    if count > 0 {
        output.push('\n');
    }
    print!("{output}");
}

