fn append_run(output: &mut String, start: i128, end: i128, length: usize) {
    let mut append_number = |number: i128| {
        if !output.is_empty() {
            output.push(',');
        }
        output.push_str(&number.to_string());
    };

    if length >= 3 {
        if !output.is_empty() {
            output.push(',');
        }
        output.push_str(&start.to_string());
        output.push('-');
        output.push_str(&end.to_string());
    } else {
        append_number(start);
        if length == 2 {
            append_number(end);
        }
    }
}

