fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: usize = values.next().unwrap().parse().unwrap();
    let mut output = String::new();

    if n > 0 {
        let mut start: i64 = values.next().unwrap().parse().unwrap();
        let mut end = start;

        for _ in 1..n {
            let current: i64 = values.next().unwrap().parse().unwrap();

            if end.checked_add(1) == Some(current) {
                end = current;
            } else {
                append_run(&mut output, start, end);
                start = current;
                end = current;
            }
        }

        append_run(&mut output, start, end);
    }

    println!("{output}");
}

fn append_run(output: &mut String, start: i64, end: i64) {
    if !output.is_empty() {
        output.push(',');
    }

    let run_len = end.checked_sub(start).and_then(|difference| difference.checked_add(1));
    if run_len.is_some_and(|length| length >= 3) {
        output.push_str(&start.to_string());
        output.push('-');
        output.push_str(&end.to_string());
    } else {
        output.push_str(&start.to_string());
        if end != start {
            output.push(',');
            output.push_str(&end.to_string());
        }
    }
}

