use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: usize = values.next().unwrap().parse().unwrap();
    if n == 0 {
        println!();
        return;
    }

    let first: i64 = values.next().unwrap().parse().unwrap();
    let mut start = first;
    let mut end = first;
    let mut output: Vec<String> = Vec::new();

    for _ in 1..n {
        let current: i64 = values.next().unwrap().parse().unwrap();
        if end.checked_add(1) == Some(current) {
            end = current;
        } else {
            append_run(&mut output, start, end);
            start = current;
            end = current;
        }
    }

    append_run(&mut output, start, end);
    println!("{}", output.join(","));
}

fn append_run(output: &mut Vec<String>, start: i64, end: i64) {
    if start.checked_add(1).and_then(|value| value.checked_add(1))
        .is_some_and(|third| third <= end)
    {
        output.push(format!("{start}-{end}"));
    } else {
        output.push(start.to_string());
        if end != start {
            output.push(end.to_string());
        }
    }
}

