use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut fields = input.split_whitespace();

    let count: usize = fields.next().unwrap().parse().unwrap();
    let mut totals: BTreeMap<&str, i128> = BTreeMap::new();

    for _ in 0..count {
        let name = fields.next().unwrap();
        let change: i128 = fields.next().unwrap().parse().unwrap();
        *totals.entry(name).or_insert(0) += change;
    }

    let mut output = String::new();
    for (name, total) in totals {
        output.push_str(name);
        output.push(' ');
        output.push_str(&total.to_string());
        output.push('\n');
    }
    print!("{output}");
}

